'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlarft = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var DIRECTS = [
	'forward',
	'backward'
];
var STOREVS = [
	'columns',
	'rows'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {string} direct - direction
* @param {string} storev - storage
* @param {PositiveInteger} K - order of T
* @returns {Function} benchmark function
*/
function createBenchmark( order, direct, storev, K ) {
	var strideV1;
	var strideV2;
	var strideT1;
	var strideT2;
	var vlen;
	var LDV = K;
	var TAU;
	var N = K + 2;
	var T;
	var V;
	var i;

	if ( storev === 'columns' ) {
		LDV = N;
		if ( isRowMajor( order ) ) {
			vlen = ( (N-1) * N ) + K;
		} else {
			vlen = N * K;
		}
		V = uniform( vlen, -10.0, 10.0, opts );
		for ( i = 0; i < K; i++ ) {
			if ( order === 'row-major' ) {
				V[ (i*N) + i ] = 1.0;
			} else {
				V[ i + (i*N) ] = 1.0;
			}
		}
	} else {
		LDV = K;
		if ( isRowMajor( order ) ) {
			vlen = ( (K-1) * K ) + N;
		} else {
			vlen = K * N;
		}
		V = uniform( vlen, -10.0, 10.0, opts );
		for ( i = 0; i < K; i++ ) {
			if ( order === 'row-major' ) {
				V[ (i*K) + i ] = 1.0;
			} else {
				V[ i + (i*K) ] = 1.0;
			}
		}
	}
	TAU = uniform( K, -10.0, 10.0, opts );
	T = new Float64Array( K*K );
	if ( isRowMajor( order ) ) {
		strideV1 = LDV;
		strideV2 = 1;
		strideT1 = K;
		strideT2 = 1;
	} else { // order === 'column-major'
		strideV1 = 1;
		strideV2 = LDV;
		strideT1 = 1;
		strideT2 = K;
	}

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var z;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dlarft( direct, storev, N, K, V, strideV1, strideV2, 0, TAU, 1, 0, T, strideT1, strideT2, 0 );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var storev;
	var direct;
	var order;
	var min;
	var max;
	var K;
	var f;
	var i;
	var j;
	var k;
	var l;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( l = 0; l < LAYOUTS.length; l++ ) {
		order = LAYOUTS[ l ];
		for ( k = 0; k < DIRECTS.length; k++ ) {
			direct = DIRECTS[ k ];
			for ( j = 0; j < STOREVS.length; j++ ) {
				storev = STOREVS[ j ];
				for ( i = min; i <= max; i++ ) {
					K = floor( pow( pow( 10, i ), 1.0/2.0 ) );
					if ( K === 0 ) {
						K = 1;
					}
					f = createBenchmark( order, direct, storev, K );
					bench( format( '%s::ndarray:order=%s:direct=%s,storev=%s,size=%d', pkg, order, direct, storev, K ), f );
				}
			}
		}
	}
}

main();
